import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load ceramic grain texture
  const grainsTexture = ctx.textureLoader.load(
    '/prism-assets/chrome/ceramic-grain.map.png'
  );
  grainsTexture.colorSpace = THREE.SRGBColorSpace;

  // Create billboard plane with atlas region aspect ratio (512:320 = 1.6)
  const aspectRatio = 512 / 320;
  const planeHeight = 2.0;
  const planeWidth = planeHeight * aspectRatio;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Material using TSL texture node
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode(grainsTexture),
    transparent: true,
    side: THREE.DoubleSide,
  });

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render headline text via fontAtlas
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: config.textContent,
      fontSize: 0.34, // headline scale from design tokens
      fontWeight: 400,
      fontFamily: 'Lora', // display serif
      color: config.colors?.ink || '#16161d',
      align: 'center',
      anchorX: 'center',
      anchorY: 'middle',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Cleanup resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    grainsTexture.dispose();
  };

  return group;
}
